import sys

def main():
    N = int(sys.stdin.readline())
    A = list(map(int, sys.stdin.readline().split()))
    B = list(map(int, sys.stdin.readline().split()))

    # Step 0: check all non -1 values are >=0
    for a in A:
        if a != -1 and a < 0:
            print("No")
            return
    for b in B:
        if b != -1 and b < 0:
            print("No")
            return

    # Step 1: collect sums where both are not -1
    sums = []
    for a, b in zip(A, B):
        if a != -1 and b != -1:
            sums.append(a + b)

    if len(sums) > 0:
        first_sum = sums[0]
        for s in sums:
            if s != first_sum:
                print("No")
                return
        S = first_sum
        # Check for positions where A is fixed and B is -1, or vice versa
        valid = True
        for i in range(N):
            a_i = A[i]
            b_i = B[i]
            if a_i != -1 and b_i == -1:
                if a_i > S:
                    valid = False
                    break
            elif b_i != -1 and a_i == -1:
                if b_i > S:
                    valid = False
                    break
        if valid:
            print("Yes")
        else:
            print("No")
    else:
        # Case 2: no positions with both not -1
        L = -float('inf')
        for i in range(N):
            a_i = A[i]
            b_i = B[i]
            if a_i != -1 and b_i == -1:
                L = max(L, a_i)
            elif b_i != -1 and a_i == -1:
                L = max(L, b_i)
        S = max(L, 0)
        print("Yes")

if __name__ == "__main__":
    main()

